import math
last=0.0
count=0
def control(obs):
 global last,count
 cam=obs.get('views',{}).get('camera')
 h=obs['hitch_deg']
 if not cam:
  return (last,-0.45,-23)
 th=math.radians(obs['rig']['trailer_heading_deg'])
 c,s=math.cos(th),math.sin(th)
 rear=obs['rig']['trailer_rear']
 origin=cam['origin']
 sides=[[],[]]
 for b,d in cam['walls']:
  b=math.radians(b)
  dx=origin[0]+d*math.cos(b)-rear[0]
  dy=origin[1]+d*math.sin(b)-rear[1]
  u=-c*dx-s*dy
  y=-s*dx+c*dy
  if u>0.4:
   sides[0 if y<0 else 1].append((u,y))
 def at(points,u):
  points=sorted(points)
  for a,b in zip(points,points[1:]):
   if a[0]<=u<=b[0]:
    f=(u-a[0])/max(0.001,b[0]-a[0])
    return a[1]+f*(b[1]-a[1])
  return min(points,key=lambda p:abs(p[0]-u))[1]
 if all(sides):
  u=4.0
  mid=(at(sides[0],u)+at(sides[1],u))/2
  desired=math.degrees(math.atan(7.3*mid/(u*u)))
  desired=max(-24,min(24,desired))
  cmd=2.5*h-1.75*desired
  last=0.7*last+0.3*max(-34,min(34,cmd))
 count+=1
 if count%100==0:
  print('hitch',round(h,1),'steer',round(last,1),'remaining',obs['progress']['remaining'])
 return (last,-0.65 if obs['progress']['remaining']>6 else -0.45,-23)

