import math
def control(o):
 h=o['hitch_deg']; a=math.radians(h); c=math.cos(a); s=math.sin(a)
 rear=o['rig']['trailer_rear']; rx=c*rear[0]-s*rear[1]
 pts=[]
 view=o['views'].get('left_mirror')
 if view:
  ox,oy=view['origin']
  for b,d in view['walls']:
   b=math.radians(b); x=ox+d*math.cos(b); y=oy+d*math.sin(b)
   X=c*x-s*y; Y=s*x+c*y
   if rx-7<X<rx+2 and Y>0.7: pts.append((X,Y))
 if len(pts)<4: return (max(-40,min(40,2*h)), -0.25,64)
 mx=sum(p[0] for p in pts)/len(pts); my=sum(p[1] for p in pts)/len(pts)
 slope=sum((x-mx)*(y-my) for x,y in pts)/max(.1,sum((x-mx)**2 for x,y in pts))
 err=my+slope*(rx-4-mx)-2.6
 desired=math.degrees(math.atan2(7.2*err,16))
 desired=max(-24,min(24,desired))
 steer=max(-42,min(42,.51*h+2.1*(h-desired)))
 return (steer,-0.65 if abs(h)<20 else -0.4,64)

