import math
filt=0.0
def control(obs):
 global filt
 h=math.radians(obs['hitch_deg'])
 cam=obs.get('views',{}).get('camera')
 if cam:
  sides=[[],[]]
  for b,d in cam.get('walls',[]):
   a=math.radians(b)
   x=d*math.cos(a); y=d*math.sin(a)
   s=-math.cos(h)*x+math.sin(h)*y
   z=math.sin(h)*x+math.cos(h)*y
   if s>0: sides[0 if z<0 else 1].append((s,z))
  def at(points,s):
   points=sorted(points)
   for p,q in zip(points,points[1:]):
    if p[0]<=s<=q[0]:
     return p[1]+(q[1]-p[1])*(s-p[0])/max(.001,q[0]-p[0])
   return min(points,key=lambda p:abs(p[0]-s))[1]
  if all(sides):
   centre=(at(sides[0],7)+at(sides[1],7))/2
   desired=math.degrees(math.atan(20.4*centre/49))
   desired=max(-55,min(55,desired))
   filt+=0.09*(desired-filt)
 steer=0.38*obs['hitch_deg']+1.5*(obs['hitch_deg']-filt)
 return (max(-42,min(42,steer)),-0.9,-41)

